Write platform-specific storage implementations for `androidMain`, `iosMain`, and `jvmMain` source sets of the `client` KMP module.

## Project root: `/Users/se/git/cc-experiments`
## Module: `client/`

## Contracts from commonMain (already defined, DO NOT modify):

```kotlin
// com.bookreads.storage.AppPreferences (commonMain)
@Serializable
data class AppPreferences(
    val username: String? = null,
    val activeSession: ActiveSession? = null,
)

@Serializable
data class ActiveSession(
    val clientId: String,
    val bookTitle: String,
    val startedAt: String,
    val elapsedSec: Long,
)

// com.bookreads.storage.LocalStorageService (commonMain)
interface LocalStorageService {
    fun getUsername(): Flow<String?>
    suspend fun setUsername(username: String?)
    fun getActiveSession(): Flow<ActiveSession?>
    suspend fun saveActiveSession(session: ActiveSession)
    suspend fun clearActiveSession()
}

// com.bookreads.di.ClientModule (commonMain)
expect val clientPlatformModule: Module
```

## Files to create

### For each of androidMain, iosMain, jvmMain — create these files:

All three platforms use the SAME `PrefSerializer` and `PrefServiceDataStore` code (identical logic, different path).

---

### androidMain:

**`client/src/androidMain/kotlin/com/bookreads/storage/PrefSerializer.kt`**
```kotlin
package com.bookreads.storage

import androidx.datastore.core.okio.OkioSerializer
import kotlinx.serialization.json.Json
import okio.BufferedSink
import okio.BufferedSource

internal class PrefSerializer : OkioSerializer<AppPreferences> {
    private val json = Json { ignoreUnknownKeys = true }

    override val defaultValue: AppPreferences get() = AppPreferences()

    override suspend fun readFrom(source: BufferedSource): AppPreferences =
        try {
            json.decodeFromString(AppPreferences.serializer(), source.readUtf8())
        } catch (_: Throwable) {
            defaultValue
        }

    override suspend fun writeTo(t: AppPreferences, sink: BufferedSink) {
        sink.writeUtf8(json.encodeToString(AppPreferences.serializer(), t))
    }
}
```

**`client/src/androidMain/kotlin/com/bookreads/storage/PrefServiceDataStore.kt`**
```kotlin
package com.bookreads.storage

import androidx.datastore.core.DataStoreFactory
import androidx.datastore.core.okio.OkioStorage
import kotlinx.coroutines.flow.Flow
import kotlinx.coroutines.flow.map
import okio.FileSystem
import okio.Path

internal class PrefServiceDataStore(private val path: Path) : LocalStorageService {
    private val dataStore by lazy {
        DataStoreFactory.create(
            storage = OkioStorage(
                fileSystem = FileSystem.SYSTEM,
                serializer = PrefSerializer(),
                producePath = { path },
            ),
        )
    }

    override fun getUsername(): Flow<String?> = dataStore.data.map { it.username }

    override suspend fun setUsername(username: String?) {
        dataStore.updateData { it.copy(username = username) }
    }

    override fun getActiveSession(): Flow<ActiveSession?> = dataStore.data.map { it.activeSession }

    override suspend fun saveActiveSession(session: ActiveSession) {
        dataStore.updateData { it.copy(activeSession = session) }
    }

    override suspend fun clearActiveSession() {
        dataStore.updateData { it.copy(activeSession = null) }
    }
}
```

**`client/src/androidMain/kotlin/com/bookreads/di/ClientAndroidModule.kt`**
```kotlin
package com.bookreads.di

import android.content.Context
import com.bookreads.storage.LocalStorageService
import com.bookreads.storage.PrefServiceDataStore
import okio.Path.Companion.toOkioPath
import org.koin.android.ext.koin.androidContext
import org.koin.core.module.Module
import org.koin.dsl.module

actual val clientPlatformModule: Module = module {
    single<LocalStorageService> {
        val context: Context = androidContext()
        val path = context.filesDir.resolve("bookreads_prefs.json").toOkioPath()
        PrefServiceDataStore(path)
    }
}
```

