```kotlin
package com.bookreads.di

import com.bookreads.storage.LocalStorageService
import com.bookreads.storage.PrefServiceDataStore
import okio.Path.Companion.toPath
import org.koin.core.module.Module
import org.koin.dsl.module
import platform.Foundation.NSDocumentDirectory
import platform.Foundation.NSFileManager
import platform.Foundation.NSUserDomainMask

actual val clientPlatformModule: Module = module {
    single<LocalStorageService> {
        val docsDir = NSFileManager.defaultManager.URLForDirectory(
            NSDocumentDirectory, NSUserDomainMask, null, true, null,
        )?.path ?: error("Cannot find documents directory")
        val path = "$docsDir/bookreads_prefs.json".toPath()
        PrefServiceDataStore(path)
    }
}
```

